UPDATE ck_shop_product
SET frozen_stock = frozen_stock + #{quantity}
WHERE id = #{productId}
  AND del_flag = 0
  AND status = 'Y'
  AND stock - frozen_stock >= #{quantity}

UPDATE ck_shop_product
SET frozen_stock = frozen_stock - #{quantity}
WHERE id = #{productId}
  AND frozen_stock >= #{quantity}

UPDATE ck_shop_product
SET stock        = stock - #{quantity},
    frozen_stock = frozen_stock - #{quantity},
    sales_count  = sales_count + #{quantity}
WHERE id = #{productId}
  AND stock >= #{quantity}
  AND frozen_stock >= #{quantity}

UPDATE ck_shop_product
SET stock = stock + #{quantity}
WHERE id = #{productId}

UPDATE ck_shop_product
SET sales_count = sales_count + #{quantity}
WHERE id = #{productId}

UPDATE ck_shop_product_sku_combination
SET frozen_stock = frozen_stock + #{quantity}
WHERE id = #{skuId}
  AND del_flag = 0
  AND saleable = 'Y'
  AND stock - frozen_stock >= #{quantity}

UPDATE ck_shop_product_sku_combination
SET frozen_stock = frozen_stock - #{quantity}
WHERE id = #{skuId}
  AND frozen_stock >= #{quantity}

UPDATE ck_shop_product_sku_combination
SET stock        = stock - #{quantity},
    frozen_stock = frozen_stock - #{quantity}
WHERE id = #{skuId}
  AND stock >= #{quantity}
  AND frozen_stock >= #{quantity}

UPDATE ck_shop_product_sku_combination
SET stock = stock + #{quantity}
WHERE id = #{skuId}

UPDATE ck_shop_promotion
SET seckill_stock = seckill_stock - #{quantity}
WHERE id = #{promotionId}
  AND seckill_stock IS NOT NULL
  AND seckill_stock >= #{quantity}

UPDATE ck_shop_promotion
SET seckill_stock = seckill_stock + #{quantity}
WHERE id = #{promotionId}
  AND seckill_stock IS NOT NULL
